// The review document (SPEC §8.4): every reviewable item in reading order, with its id, so the
// drafts can be reviewed in one pass.
import { reviewableItems, unreviewedOf } from '../../../src/domain/reviewable.ts';
import type { Portion } from '../../../src/domain/types.ts';
import { contentRules } from '../config.ts';
import type { ChapterLayers } from '../load.ts';
import { cardsSection, questionsSection, textSection } from './sections.ts';

const INTRO =
  'Generated by `npm run review` from the JSON in `content/`. Do not edit the layout by hand: mark corrections next to an item (or edit the JSON directly), and Claude Code applies them and sets `reviewed: true` only for the items you approve.';

export function reviewDocument(all: ChapterLayers, p: Portion, rules = contentRules) {
  const unreviewed = unreviewedOf(reviewableItems({ ...all, portion: p })).length;
  const text = [
    `# Content review: ${p.label.he}`,
    '',
    INTRO,
    '',
    `**Status:** ${unreviewed} item(s) to review.`,
    '',
    ...textSection(all, p),
    ...questionsSection(all, p, rules),
    ...cardsSection(all, p),
  ].join('\n');
  return { text, unreviewed };
}
